contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(caller != address(0)); // avoid zero-address weirdness in comparison

        // Read the optimisticAsserter address via the public getter
        address optimistic = address(c.optimisticAsserter());

        // We will attempt to call requestPrice as if msg.sender == caller.
        // Since the test contract is the msg.sender for external calls, we cannot change msg.sender.
        // To simulate both cases, we compare caller to optimistic and branch only in checking outcome.
        // Make the actual call: it will originate from this contract. The property asserts that the call
        // succeeds iff this contract is the optimisticAsserter. So we first check whether this contract
        // equals optimistic. That is our observable condition.

        // Perform the call and capture revert status.
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: the call reverts exactly when this contract is not the optimisticAsserter.
        // Translate to observable condition: reverted == (address(this) != optimistic)
        assert(reverted == (address(this) != optimistic));
    }

    // allow receiving Ether if needed by other tests
    receive() external payable {}
}

