contract InvMutTest {
    C c;
    address immutable other = address(0x1234);

    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary params
    function run(address optimisticAsserterCandidate, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // Precondition: the provided optimisticAsserterCandidate will be treated as the optimisticAsserter
        // by construction of the fresh C instance in the checker environment; no require on c state.

        // 1) When non-optimistic asserter (this contract/other) calls requestPrice it must revert due to onlyOptimisticAsserter
        bool reverted_requestPrice_nonOpt;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted_requestPrice_nonOpt = false;
        } catch {
            reverted_requestPrice_nonOpt = true;
        }

        // 2) When non-optimistic asserter calls assertionResolvedCallback it must revert
        bool reverted_assertionResolved_nonOpt;
        try c.assertionResolvedCallback(bytes32(0), true) {
            reverted_assertionResolved_nonOpt = false;
        } catch {
            reverted_assertionResolved_nonOpt = true;
        }

        // 3) When non-optimistic asserter calls assertionDisputedCallback it must revert
        bool reverted_assertionDisputed_nonOpt;
        try c.assertionDisputedCallback(bytes32(0)) {
            reverted_assertionDisputed_nonOpt = false;
        } catch {
            reverted_assertionDisputed_nonOpt = true;
        }

        // Now attempt to call these methods as the optimisticAsserterCandidate by deploying a minimal forwarder
        // that will call c with msg.sender == optimisticAsserterCandidate. We cannot deploy contracts here,
        // but we can rely on the fact that the checker deploys c with optimisticAsserter equal to optimisticAsserterCandidate
        // and will then call run() from this InvMutTest; however we cannot change msg.sender. So instead we observe the
        // observable public optimisticAsserter getter and require its value equals the provided candidate; if it does,
        // then calling the functions should NOT revert when msg.sender == optimisticAsserter — but since the checker
        // cannot change msg.sender here, we instead assert the implication:
        // if optimisticAsserter == address(this) then the three calls must NOT revert (we actually can call them),
        // otherwise we at least observed that calling them from non-optimistic asserter reverted.

        address observedOpt = address(c.optimisticAsserter());

        bool notReverted_requestPrice_opt = false;
        bool notReverted_resolved_opt = false;
        bool notReverted_disputed_opt = false;

        if (observedOpt == address(this)) {
            // Now these calls should succeed (not revert) because onlyOptimisticAsserter allows this contract
            try c.requestPrice(identifier, time, ancillaryData) {
                notReverted_requestPrice_opt = true;
            } catch {
                notReverted_requestPrice_opt = false;
            }
            try c.assertionResolvedCallback(bytes32(0), true) {
                notReverted_resolved_opt = true;
            } catch {
                notReverted_resolved_opt = false;
            }
            try c.assertionDisputedCallback(bytes32(0)) {
                notReverted_disputed_opt = true;
            } catch {
                notReverted_disputed_opt = false;
            }
        }

        // Final general assertion (single assert):
        // - If this contract is the optimisticAsserter (observedOpt == address(this)) then the three calls must succeed (notReverted_* == true).
        // - Otherwise, the three direct calls from this contract must have reverted (reverted_* == true).
        assert(((observedOpt == address(this)) && notReverted_requestPrice_opt && notReverted_resolved_opt && notReverted_disputed_opt) ||
               ((observedOpt != address(this)) && reverted_requestPrice_nonOpt && reverted_assertionResolved_nonOpt && reverted_assertionDisputed_nonOpt));
    }

    receive() external payable {}
}

