contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take two addresses as inputs: a caller that equals optimisticAsserter and a caller that is different.
    // Because this contract deployed c in the checker setup, optimisticAsserter() is readable.
    function run(address maybeAsserter, address other, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool assertedTruthfully) public payable {
        require(maybeAsserter != other, "inputs must differ");
        // Read the optimisticAsserter address from c (public getter)
        address actualAsserter = address(c.optimisticAsserter());

        // We will attempt calls from this contract (msg.sender == address(this)). The contract C enforces onlyOptimisticAsserter modifier requiring msg.sender == optimisticAsserter.
        // So calls performed directly from this contract should revert unless this contract equals the optimisticAsserter value.
        // We record whether each call reverts.
        bool reqPriceReverted;
        bool resolvedCbReverted;
        bool disputedCbReverted;

        // requestPrice is onlyOptimisticAsserter; it will revert unless this contract is the optimistic asserter address.
        try c.requestPrice(identifier, time, ancillaryData) {
            reqPriceReverted = false;
        } catch {
            reqPriceReverted = true;
        }

        // assertionResolvedCallback likewise
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            resolvedCbReverted = false;
        } catch {
            resolvedCbReverted = true;
        }

        // assertionDisputedCallback likewise
        try c.assertionDisputedCallback(assertionId) {
            disputedCbReverted = false;
        } catch {
            disputedCbReverted = true;
        }

        // The general rule: these calls succeed (do not revert) iff this contract is the optimisticAsserter recorded by c.
        // That is, if address(this) == actualAsserter then none should revert; otherwise all should revert.
        assert(
            ((address(this) == actualAsserter) && (!reqPriceReverted) && (!resolvedCbReverted) && (!disputedCbReverted))
            || ((address(this) != actualAsserter) && (reqPriceReverted) && (resolvedCbReverted) && (disputedCbReverted))
        );
    }

    receive() external payable {}
}

