contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function with inputs: caller address to simulate different msg.sender via delegatecall is not possible,
    // but we can check that when called from this contract (which is not the optimisticAsserter passed to C constructor in the harness),
    // the three restricted functions revert. We capture reverts via try/catch.
    function run(bytes32 id, bytes calldata ancillary, uint256 t) public payable {
        require(true);

        bool reqReverted;
        bool resReverted;
        bool disReverted;

        // requestPrice is onlyOptimisticAsserter; calling from this contract should revert
        try c.requestPrice(id, t, ancillary) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // assertionResolvedCallback is onlyOptimisticAsserter; calling from this contract should revert
        try c.assertionResolvedCallback(id, true) {
            resReverted = false;
        } catch {
            resReverted = true;
        }

        // assertionDisputedCallback is onlyOptimisticAsserter; calling from this contract should revert
        try c.assertionDisputedCallback(id) {
            disReverted = false;
        } catch {
            disReverted = true;
        }

        // General rule: when called by an address different from optimisticAsserter (here, address(this)),
        // all three onlyOptimisticAsserter-protected functions must revert. We observe optimisticAsserter via public getter.
        address optimistic = address(c.optimisticAsserter());

        // If this contract is the optimistic asserter (deployed so), then the calls should NOT revert. Otherwise they MUST revert.
        // Assert that the observed revert flags match whether this contract equals the optimisticAsserter.
        assert((address(this) == optimistic && !reqReverted && !resReverted && !disReverted) || (address(this) != optimistic && reqReverted && resReverted && disReverted));
    }

    receive() external payable {}
}

