        asserter = payable(address(c.optimisticAsserter()));
    }

    // single public entry that will be fuzzed: callerAddressFlag chooses who calls requestPrice
    // if callerAddressFlag == 0 -> call from optimisticAsserter (should succeed), else from this contract (should revert)
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, uint8 callerAddressFlag) public payable {
        require(callerAddressFlag <= 1, "flag must be 0 or 1");
        // snapshot contract balance before
        uint256 balanceBefore = address(c).balance;

        bool reverted;

        if (callerAddressFlag == 0) {
            // simulate call coming from optimisticAsserter by using the optimisticAsserter contract to call c.requestPrice
            // We cannot make an external account call, but we can call via the recorded address if it's a contract known to exist.
            // The spec guarantees optimisticAsserter is an address; attempt a low-level call from this contract using delegatecall is not allowed.
            // Instead we check behavior when this contract (not the asserter) calls: it must revert due to onlyOptimisticAsserter.
            // To still reach the branch for the intended good case, if the optimisticAsserter equals address(this) we can call successfully.
            if (asserter == address(this)) {
                // this contract is the optimisticAsserter, so call should not revert
                try c.requestPrice(identifier, time, ancillaryData) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // cannot call from the recorded optimisticAsserter, so mark reverted = true to reflect that requestPrice cannot be
                // invoked by this contract as the optimisticAsserter in this scenario. The property below will accept both possibilities
                // by relating reverted to whether asserter == address(this).
                try c.requestPrice(identifier, time, ancillaryData) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // callerAddressFlag == 1: call from this contract (not the optimisticAsserter) — should revert unless optimisticAsserter == this
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 balanceAfter = address(c).balance;

        // General rule:
        // If the caller is the optimisticAsserter (asserter == address(this)), requestPrice must not revert when called from this contract;
        // otherwise it must revert. Additionally, regardless of success or revert, the contract's Ether balance must be unchanged.
        assert(((asserter == address(this)) == (!reverted)) && balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

