        // Observe balance after the call
        uint256 afterBalance = address(c).balance;

        // General rule asserted:
        // If this contract is NOT the optimisticAsserter then the call must revert.
        // If this contract IS the optimisticAsserter then the call must NOT revert and must not change C's balance.
