contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entry that tests that non-optimisticAsserter callers cannot invoke onlyOptimisticAsserter-protected functions.
    // We take an arbitrary address encoded as uint160 to act as a caller (not equal to optimisticAsserter())
    function run(uint160 callerAsInt, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool truth) public payable {
        require(true);

        // Derive an address from the input; if it equals optimisticAsserter, try to ensure we still exercise the non-authorized path
        address other = address(uint160(callerAsInt));
        address optimistic = address(c.optimisticAsserter());

        // If the derived address equals optimistic, slightly change it to guarantee it's different
        if (other == optimistic) {
            // flip low bit (keeps as valid address)
            other = address(uint160(other) ^ 1);
        }

        // We will attempt to call the three onlyOptimisticAsserter functions from this contract but using call with a forged msg.sender is impossible in Solidity.
        // Instead, we check that when the optimisticAsserter is not msg.sender, direct external calls revert by invoking them from this contract
        // only when this contract is NOT the optimisticAsserter. The rule: if this contract is not the optimisticAsserter, calls must revert.

        bool amOptimistic = (address(this) == optimistic);

        // Try requestPrice
        bool reqPriceReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqPriceReverted = false;
        } catch {
            reqPriceReverted = true;
        }

        // Try assertionResolvedCallback
        bool resolvedReverted;
        try c.assertionResolvedCallback(assertionId, truth) {
            resolvedReverted = false;
        } catch {
            resolvedReverted = true;
        }

        // Try assertionDisputedCallback
        bool disputedReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        // General rule: if this contract is NOT the optimisticAsserter, all three protected calls must revert;
        // if this contract IS the optimisticAsserter, none of them are required to revert (implementation may allow).
        assert(amOptimistic || (reqPriceReverted && resolvedReverted && disputedReverted));
    }

    receive() external payable {}
}

